DROP TABLE saved_experiences;
DROP TABLE sessions;
DROP TABLE users;
ALTER TABLE businesses RENAME COLUMN region TO state;
ALTER TABLE businesses ALTER COLUMN address DROP NOT NULL, ALTER COLUMN city DROP NOT NULL;
UPDATE businesses SET address=NULL WHERE btrim(address)='';
UPDATE businesses SET city=NULL WHERE btrim(city)='';
-- Keep incomplete legacy locations inactive, without inventing a location.
UPDATE businesses SET is_active=FALSE WHERE (latitude IS NULL OR longitude IS NULL) AND (city IS NULL OR NULLIF(btrim(state),'') IS NULL);
ALTER TABLE businesses ADD CONSTRAINT venue_location_required CHECK
 (NOT is_active OR ((city IS NOT NULL AND btrim(city)<>'' AND state IS NOT NULL AND btrim(state)<>'') OR (latitude IS NOT NULL AND longitude IS NOT NULL)));
ALTER TABLE businesses DROP COLUMN description, DROP COLUMN phone, DROP COLUMN image_url, DROP COLUMN website_url, DROP COLUMN time_zone;
ALTER TABLE experiences DROP CONSTRAINT price_requires_currency;
ALTER TABLE experiences DROP CONSTRAINT experiences_type_check;
ALTER TABLE experiences ALTER COLUMN description DROP NOT NULL, ALTER COLUMN type SET DEFAULT 'OTHER';
ALTER TABLE experiences ADD CONSTRAINT experiences_type_check CHECK(type IN ('OTHER','OFFER','EVENT','ACTIVITY','SPECIAL'));
ALTER TABLE experiences DROP COLUMN currency, DROP COLUMN price_label, DROP COLUMN requirements, DROP COLUMN image_url;
ALTER TABLE experience_schedules DROP CONSTRAINT valid_once_schedule, DROP CONSTRAINT valid_schedule_times, DROP CONSTRAINT valid_all_day;
UPDATE experience_schedules SET end_date=start_date+1 WHERE kind='ONCE' AND ends_next_day;
-- Weekly overnight dates remain the recurrence range; end time crossing midnight determines the following day.
ALTER TABLE experience_schedules ALTER COLUMN time_zone DROP NOT NULL, ALTER COLUMN start_time DROP NOT NULL, ALTER COLUMN end_time DROP NOT NULL, ALTER COLUMN kind SET DEFAULT 'ONCE';
ALTER TABLE experience_schedules ADD CONSTRAINT schedule_start_required CHECK(all_day OR start_time IS NOT NULL);
ALTER TABLE experience_schedules ADD CONSTRAINT schedule_end_valid CHECK(all_day OR end_time IS NULL OR kind='WEEKLY' OR COALESCE(end_date,start_date)>start_date OR end_time>start_time);
ALTER TABLE experience_schedule_days ADD COLUMN experience_id UUID;
UPDATE experience_schedule_days d SET experience_id=s.experience_id FROM experience_schedules s WHERE d.schedule_id=s.id;
ALTER TABLE experience_schedule_days DROP CONSTRAINT experience_schedule_days_pkey, DROP COLUMN schedule_id;
ALTER TABLE experience_schedules DROP CONSTRAINT experience_schedules_pkey, DROP CONSTRAINT experience_schedules_experience_id_key;
ALTER TABLE experience_schedules DROP COLUMN id, DROP COLUMN ends_next_day, DROP COLUMN created_at, DROP COLUMN updated_at;
ALTER TABLE experience_schedules ADD PRIMARY KEY(experience_id);
ALTER TABLE experience_schedule_days ALTER COLUMN experience_id SET NOT NULL;
ALTER TABLE experience_schedule_days ADD PRIMARY KEY(experience_id,iso_weekday), ADD FOREIGN KEY(experience_id) REFERENCES experience_schedules(experience_id) ON DELETE CASCADE;
ALTER TABLE categories DROP COLUMN created_at, DROP COLUMN updated_at;
-- Drop retired fields in queued snapshots as well, while retaining source/review identity.
UPDATE event_submissions SET payload=jsonb_set(payload,'{event}',
 (payload->'event')-'currency'-'offer'-'requirements'-'imageUrl') WHERE payload ? 'event';
UPDATE event_submissions SET payload=jsonb_set(payload,'{event,schedule}',
 ((payload#>'{event,schedule}')-'endsNextDay') || CASE WHEN payload#>>'{event,schedule,endsNextDay}'='true' AND payload#>>'{event,schedule,kind}'='ONCE'
 THEN jsonb_build_object('endDate',((payload#>>'{event,schedule,startDate}')::date+1)::text) ELSE '{}'::jsonb END)
 WHERE jsonb_typeof(payload#>'{event,schedule}')='object';
UPDATE event_submissions SET payload=jsonb_set(payload,'{venue,proposal}',
 ((payload#>'{venue,proposal}')-'region') || CASE WHEN payload#>>'{venue,proposal,region}' IS NOT NULL THEN jsonb_build_object('state',payload#>>'{venue,proposal,region}') ELSE '{}'::jsonb END)
 WHERE jsonb_typeof(payload#>'{venue,proposal}')='object';
COMMIT;
